; EXODUS.BIN: Ultima III (Origin 1983, PC version by James R. Van Artsdalen).
; Generated by tools/gen.py; tools/build.py builds it (MASM, LINK, then the image from 0100).
; EQUIP: ready weapon and armour, talk, gold (7D1A-8190).
;
; The amount helpers of Hand Equipment and the shops (ReadAmount reads up to 4 digits, TransferBcd moves
; a BCD amount between two counts), the shared error exits (MsgNoneLeft ... MsgIncapacitated:
; message, sound, FlushKeys, back to MainLoop), AddMoves (the move counter), Ready a weapon
; (CmdReady/ReadyWeapon) and Wear armour (CmdWear/L7EFA) with the class limits, FindMonster (which creature
; stands on a cell), the T command Transact (CmdTransact: talk to a creature, to Lord British for a
; level, or buy across a shop counter) and ChestLoot (the gold and items in a chest).
; Strings and tables used here live in ACTIONS (795B-7AAA).
CODE SEGMENT BYTE PUBLIC
ASSUME CS:CODE, DS:CODE, ES:CODE, SS:CODE
EXTRN SwapCursor:NEAR
EXTRN PutChar:NEAR
EXTRN ReadLine:NEAR
EXTRN Random:NEAR
EXTRN PrintBcdByte:NEAR
EXTRN ParseNumber:NEAR
EXTRN AskChoice:NEAR
EXTRN Sound:NEAR
EXTRN Ofs80h:BYTE
EXTRN MapText:BYTE
EXTRN MonTile:BYTE
EXTRN MoveCount:BYTE
EXTRN MoveCountB1:BYTE
EXTRN MoveCountB2:BYTE
EXTRN MoveCountB3:BYTE
EXTRN ExoticWeaponFound:BYTE
EXTRN ExoticArmourFound:BYTE
EXTRN ExtraWeaponsOk:BYTE
EXTRN ExtraArmoursOk:BYTE
EXTRN PlayerY:BYTE
EXTRN MainLoop:NEAR
EXTRN PrintMsg:NEAR
EXTRN ScrollMsg:NEAR
EXTRN MapCellAddr:NEAR
EXTRN AddGold:NEAR
EXTRN PrintName:NEAR
EXTRN IsUp:NEAR
EXTRN FlushKeys:NEAR
EXTRN AskPlayer:NEAR
EXTRN FlashView:NEAR
EXTRN InvertPlayerNum:NEAR
EXTRN ShopCmds:BYTE
EXTRN WeaponMenuKeys:BYTE
EXTRN WeaponMenuStrs:BYTE
EXTRN ArmourMenuKeys:BYTE
EXTRN ArmourMenuStrs:BYTE
EXTRN TxtNoneLeft:BYTE
EXTRN TxtWhat:BYTE
EXTRN TxtInvalidMove:BYTE
EXTRN TxtNotHere:BYTE
EXTRN TxtIncapacitated:BYTE
EXTRN MsgNoneOwned:BYTE
EXTRN MsgWeaponPrompt:BYTE
EXTRN MsgNotAllowed:BYTE
EXTRN MsgReadied:BYTE
EXTRN MsgArmourPrompt:BYTE
EXTRN MaxWeaponTbl:BYTE
EXTRN MaxArmourTbl:BYTE
EXTRN ClassLetters:BYTE
EXTRN MsgTalkDirect:BYTE
EXTRN MsgGoodDay:BYTE
EXTRN MsgWelcomeChild:BYTE
EXTRN MsgNoMore:BYTE
EXTRN MsgSeekKings:BYTE
EXTRN MsgThouGreater:BYTE
EXTRN MsgExpMore:BYTE
EXTRN MsgEatDeath:BYTE
EXTRN MsgGoldPlus:BYTE
EXTRN MsgAndA:BYTE
EXTRN MsgAnd:BYTE
EXTRN AskDirection:NEAR
EXTRN ShopHorses:NEAR
PUBLIC ReadAmount
PUBLIC TransferBcd
PUBLIC MsgNoneLeft
PUBLIC MsgWhat
PUBLIC MsgInvalidMove
PUBLIC MsgNotHere
PUBLIC MsgIncapacitated
PUBLIC AddMoves
PUBLIC CmdReady
PUBLIC ReadyWeapon
PUBLIC CmdWear
PUBLIC FindMonster
PUBLIC CmdTransact
PUBLIC ChestLoot
;------------------------------------------------------------------------------
; ReadAmount: read a number of up to 4 digits at the cursor (the field is blanked and
; read again until it holds a number). Out: AX = the number as BCD (ParseNumber's BX).
; Uses: nothing else. Called by Hand Equipment and the Grocer (A63A).
;------------------------------------------------------------------------------
ReadAmount:	pushf	;@7D1A
	push bx	;@7D1B
	push cx	;@7D1C
	push dx	;@7D1D
	push bp	;@7D1E
	push si	;@7D1F
	push di	;@7D20
	sub sp, 4	; [bp+2]: the 4 characters	;@7D21
	sub sp, 2	; [bp]: the cursor position	;@7D24
	mov bp, sp	;@7D27
	mov dx, 0	;@7D29
	call SwapCursor	;@7D2C
	mov word ptr [bp], dx	;@7D2F
ReadAmount_Retry:	call SwapCursor	;@7D32
	mov al, 20h	; blank the field	;@7D35
	call PutChar	;@7D37
	call PutChar	;@7D3A
	call PutChar	;@7D3D
	call PutChar	;@7D40
	mov dx, word ptr [bp]	;@7D43
	call SwapCursor	;@7D46
	mov cx, 4	;@7D49
	lea di, [bp+2]	;@7D4C
	call ReadLine	;@7D4F
	mov cx, bx	;@7D52
	mov si, di	;@7D54
	call ParseNumber	;@7D56
	or dx, dx	; DX < 0: no number	;@7D59
	jns ReadAmount_Done	;@7D5B
	mov al, 0FEh	; error beep	;@7D5D
	call Sound	;@7D5F
	mov dx, word ptr [bp]	;@7D62
	jmp ReadAmount_Retry	;@7D65
ReadAmount_Done:	mov ax, bx	; the BCD value	;@7D67
	add sp, 6	;@7D69
	pop di	;@7D6C
	pop si	;@7D6D
	pop bp	;@7D6E
	pop dx	;@7D6F
	pop cx	;@7D70
	pop bx	;@7D71
	popf	;@7D72
	ret	;@7D73
;------------------------------------------------------------------------------
; TransferBcd: move AX from CX to DX, all BCD words: CX -= AX, DX += AX.
; Out: AX = 0 done, 1 CX too small, 2 DX would pass 9999 (CX, DX unchanged then). For byte
; counts the callers pass AH = CH = DH = 0 and test DH <> 0 for "more than 99".
;------------------------------------------------------------------------------
TransferBcd:	pushf	;@7D74
	push bx	;@7D75
	mov bx, ax	;@7D76
	cmp ax, cx	; BCD compares like binary	;@7D78
	ja TransferBcd_Short	;@7D7A
	add al, dl	;@7D7C
	daa	;@7D7E
	xchg ah, al	;@7D7F
	adc al, dh	;@7D81
	daa	;@7D83
	jb TransferBcd_Full	;@7D84
	xchg ah, al	;@7D86
	mov dx, ax	;@7D88
	mov ax, cx	;@7D8A
	sub al, bl	;@7D8C
	das	;@7D8E
	xchg ah, al	;@7D8F
	sbb al, bh	;@7D91
	das	;@7D93
	xchg ah, al	;@7D94
	mov cx, ax	;@7D96
	mov ax, 0	;@7D98
TransferBcd_Done:	pop bx	;@7D9B
	popf	;@7D9C
	ret	;@7D9D
TransferBcd_Short:	mov ax, 1	;@7D9E
	jmp TransferBcd_Done	;@7DA1
TransferBcd_Full:	mov ax, 2	;@7DA3
	jmp TransferBcd_Done	;@7DA6
;------------------------------------------------------------------------------
; The shared error exits, jumped to from the commands: print the message, sound 0FEh (a
; beep) or 0FFh (?), drop waiting keys, back to MainLoop. Jumped to from inside a call they
; leave that call's stack behind (MainLoop does not reset SP).
;------------------------------------------------------------------------------
MsgNoneLeft:	lea si, TxtNoneLeft	; "None Left!"	;@7DA8
	call PrintMsg	;@7DAC
	mov al, 0FEh	;@7DAF
	call Sound	;@7DB1
	call FlushKeys	;@7DB4
	jmp MainLoop	;@7DB7
MsgWhat:	lea si, TxtWhat	; "<-What?"	;@7DBA
	call PrintMsg	;@7DBE
	mov al, 0FEh	;@7DC1
	call Sound	;@7DC3
	call FlushKeys	;@7DC6
	jmp MainLoop	;@7DC9
MsgInvalidMove:	lea si, TxtInvalidMove	; "Invalid Move!"	;@7DCC
	call PrintMsg	;@7DD0
	mov al, 0FFh	;@7DD3
	call Sound	;@7DD5
	call FlushKeys	;@7DD8
	jmp MainLoop	;@7DDB
MsgNotHere:	lea si, TxtNotHere	; "Not Here!"	;@7DDE
	call PrintMsg	;@7DE2
	mov al, 0FFh	;@7DE5
	call Sound	;@7DE7
	call FlushKeys	;@7DEA
	jmp MainLoop	;@7DED
MsgIncapacitated:	lea si, TxtIncapacitated	; "Incapacitated!"	;@7DF0
	call PrintMsg	;@7DF4
	mov al, 0FFh	;@7DF7
	call Sound	;@7DF9
	call FlushKeys	;@7DFC
	jmp MainLoop	;@7DFF
;------------------------------------------------------------------------------
; AddMoves: MoveCount (14BD-14C0, 8 BCD digits, low byte first) += AL (BCD).
; The main loop adds PartySize each turn. Uses: nothing.
;------------------------------------------------------------------------------
AddMoves:	pushf	;@7E02
	push ax	;@7E03
	add al, byte ptr MoveCount	;@7E04
	daa	;@7E08
	mov byte ptr MoveCount, al	;@7E09
	jae AddMoves_Done	;@7E0C
	mov al, 1	; carry into the next byte	;@7E0E
	add al, byte ptr MoveCountB1	;@7E10
	daa	;@7E14
	mov byte ptr MoveCountB1, al	;@7E15
	jae AddMoves_Done	;@7E18
	mov al, 1	;@7E1A
	add al, byte ptr MoveCountB2	;@7E1C
	daa	;@7E20
	mov byte ptr MoveCountB2, al	;@7E21
	jae AddMoves_Done	;@7E24
	mov al, 1	;@7E26
	add al, byte ptr MoveCountB3	;@7E28
	daa	;@7E2C
	mov byte ptr MoveCountB3, al	;@7E2D
AddMoves_Done:	pop ax	;@7E30
	popf	;@7E31
	ret	;@7E32
;------------------------------------------------------------------------------
; CmdReady: R, "Ready for #": ask a player and run the weapon menu (ReadyWeapon).
; In: SI = the prompt. Ends at MainLoop.
;------------------------------------------------------------------------------
CmdReady:	call PrintMsg	;@7E33
	call AskPlayer	;@7E36
	je CmdReady_Done	;@7E39
	call IsUp	;@7E3B
	jne CmdReady_Incap	;@7E3E
	call ReadyWeapon	;@7E40
CmdReady_Done:	jmp MainLoop	;@7E43
CmdReady_Incap:	jmp MsgIncapacitated	;@7E46
;------------------------------------------------------------------------------
; ReadyWeapon: "Weapon:" and the weapon menu for the player at BX (10, 17 or 18
; entries by ExoticWeaponFound/2). The class allows keys below its entry in MaxWeaponTbl; Exotic (P)
; is always allowed, Hand (A) needs nothing owned, other weapons need a count > 0.
; Prints "Readied!" and sets record byte 30h. Also used by combat (8D05). In: BX.
;------------------------------------------------------------------------------
ReadyWeapon:	pushf	;@7E48
	push ax	;@7E49
	push bx	;@7E4A
	push cx	;@7E4B
	push dx	;@7E4C
	push si	;@7E4D
	push di	;@7E4E
	cld	;@7E4F
	lea si, MsgWeaponPrompt	; "Weapon:"	;@7E50
	call PrintMsg	;@7E54
	mov cx, 0Bh	; 11 classes	;@7E57
	mov si, cx	;@7E5A
	lea di, ClassLetters	; class letters	;@7E5C
	mov al, byte ptr [bx+17h]	; class	;@7E60
	repne scasb	;@7E63
	sub si, cx	;@7E65
	dec si	; the class's index	;@7E67
	mov dl, byte ptr MaxWeaponTbl[si]	; the first key not allowed	;@7E68
	mov cx, 12h	;@7E6C
	cmp byte ptr ExoticWeaponFound, 0FFh	;@7E6F
	je ReadyWeapon_Menu	;@7E74
	mov cx, 11h	;@7E76
	cmp byte ptr ExtraWeaponsOk, 0FFh	;@7E79
	je ReadyWeapon_Menu	;@7E7E
	mov cx, 0Ah	;@7E80
ReadyWeapon_Menu:	lea di, WeaponMenuKeys	;@7E83
	lea si, WeaponMenuStrs	;@7E87
	call AskChoice	;@7E8B
	cmp al, 51h	; 'Q'	;@7E8E
	je ReadyWeapon_Quit	;@7E90
	cmp al, 1Bh	; Esc	;@7E92
	je ReadyWeapon_Quit	;@7E94
	cmp al, 50h	; 'P' Exotic	;@7E96
	je ReadyWeapon_Pick	;@7E98
	cmp al, dl	;@7E9A
	jae ReadyWeapon_NotAllowed	;@7E9C
ReadyWeapon_Pick:	mov di, bx	;@7E9E
	sub al, 41h	; index; 0 = Hand	;@7EA0
	je ReadyWeapon_Set	;@7EA2
	mov ah, 0	;@7EA4
	add bx, ax	;@7EA6
	cmp byte ptr [bx+30h], 0	; count owned	;@7EA8
	je ReadyWeapon_NoneOwned	;@7EAC
ReadyWeapon_Set:	lea si, MsgReadied	; "Readied!"	;@7EAE
	call PrintMsg	;@7EB2
	mov byte ptr [di+30h], al	; weapon readied	;@7EB5
ReadyWeapon_Done:	pop di	;@7EB8
	pop si	;@7EB9
	pop dx	;@7EBA
	pop cx	;@7EBB
	pop bx	;@7EBC
	pop ax	;@7EBD
	popf	;@7EBE
	ret	;@7EBF
ReadyWeapon_Quit:	call ScrollMsg	;@7EC0
	jmp ReadyWeapon_Done	;@7EC3
ReadyWeapon_NotAllowed:	lea si, MsgNotAllowed	; "Not allowed!"	;@7EC5
	call PrintMsg	;@7EC9
	mov al, 0FFh	;@7ECC
	call Sound	;@7ECE
	jmp ReadyWeapon_Done	;@7ED1
ReadyWeapon_NoneOwned:	call ScrollMsg	;@7ED3
	lea si, MsgNoneOwned	; "None owned"	;@7ED6
	call PrintMsg	;@7EDA
	mov al, 0FFh	;@7EDD
	call Sound	;@7EDF
	jmp ReadyWeapon_Done	;@7EE2
;------------------------------------------------------------------------------
; CmdWear: W, "Wear for #": ask a player and run the armour menu (WearArmour).
; In: SI = the prompt. Ends at MainLoop.
;------------------------------------------------------------------------------
CmdWear:	call PrintMsg	;@7EE4
	call AskPlayer	;@7EE7
	je CmdWear_Done	;@7EEA
	call IsUp	;@7EEC
	jne CmdWear_Incap	;@7EEF
	call WearArmour	;@7EF1
CmdWear_Done:	jmp MainLoop	;@7EF4
CmdWear_Incap:	jmp MsgIncapacitated	;@7EF7
;------------------------------------------------------------------------------
; WearArmour: "Armour:" and the armour menu for the player at BX (7, 9 or 10 entries by
; ExoticArmourFound/2), with the class limits of MaxArmourTbl; Exotic (H) is always allowed, Skin (A)
; needs nothing owned. Prints "Readied!" and sets record byte 28h. In: BX.
;------------------------------------------------------------------------------
WearArmour:	pushf	;@7EFA
	push ax	;@7EFB
	push bx	;@7EFC
	push cx	;@7EFD
	push dx	;@7EFE
	push si	;@7EFF
	push di	;@7F00
	cld	;@7F01
	lea si, MsgArmourPrompt	; "Armour:"	;@7F02
	call PrintMsg	;@7F06
	mov cx, 0Bh	; 11 classes	;@7F09
	mov si, cx	;@7F0C
	lea di, ClassLetters	; class letters	;@7F0E
	mov al, byte ptr [bx+17h]	; class	;@7F12
	repne scasb	;@7F15
	sub si, cx	;@7F17
	dec si	;@7F19
	mov dl, byte ptr MaxArmourTbl[si]	; the first key not allowed	;@7F1A
	mov cx, 0Ah	;@7F1E
	cmp byte ptr ExoticArmourFound, 0FFh	;@7F21
	je WearArmour_Menu	;@7F26
	mov cx, 9	;@7F28
	cmp byte ptr ExtraArmoursOk, 0FFh	;@7F2B
	je WearArmour_Menu	;@7F30
	mov cx, 7	;@7F32
WearArmour_Menu:	lea di, ArmourMenuKeys	;@7F35
	lea si, ArmourMenuStrs	;@7F39
	call AskChoice	;@7F3D
	cmp al, 51h	; 'Q'	;@7F40
	je WearArmour_Quit	;@7F42
	cmp al, 1Bh	; Esc	;@7F44
	je WearArmour_Quit	;@7F46
	cmp al, 48h	; 'H' Exotic	;@7F48
	je WearArmour_Pick	;@7F4A
	cmp al, dl	;@7F4C
	jae WearArmour_NotAllowed	;@7F4E
WearArmour_Pick:	mov di, bx	;@7F50
	sub al, 41h	; index; 0 = Skin	;@7F52
	je WearArmour_Set	;@7F54
	mov ah, 0	;@7F56
	add bx, ax	;@7F58
	cmp byte ptr [bx+28h], 0	; count owned	;@7F5A
	je WearArmour_NoneOwned	;@7F5E
WearArmour_Set:	lea si, MsgReadied	; "Readied!"	;@7F60
	call PrintMsg	;@7F64
	mov byte ptr [di+28h], al	; armour worn	;@7F67
WearArmour_Done:	pop di	;@7F6A
	pop si	;@7F6B
	pop dx	;@7F6C
	pop cx	;@7F6D
	pop bx	;@7F6E
	pop ax	;@7F6F
	popf	;@7F70
	ret	;@7F71
WearArmour_Quit:	call ScrollMsg	;@7F72
	jmp WearArmour_Done	;@7F75
WearArmour_NotAllowed:	lea si, MsgNotAllowed	; "Not allowed!"	;@7F77
	call PrintMsg	;@7F7B
	mov al, 0FFh	;@7F7E
	call Sound	;@7F80
	jmp WearArmour_Done	;@7F83
WearArmour_NoneOwned:	call ScrollMsg	;@7F85
	lea si, MsgNoneOwned	; "None owned"	;@7F88
	call PrintMsg	;@7F8C
	mov al, 0FFh	;@7F8F
	call Sound	;@7F91
	jmp WearArmour_Done	;@7F94
;------------------------------------------------------------------------------
; FindMonster: the creature slot (0-31) whose MonX, MonY are DL, DH, searched from
; slot 31 down; empty slots (MonTile 0) are skipped. Out: BX = the slot or 0FFFFh.
;------------------------------------------------------------------------------
FindMonster:	pushf	;@7F96
	push cx	;@7F97
	push si	;@7F98
	mov cx, 20h	;@7F99
	mov si, 1Fh	;@7F9C
	lea si, MonTile[si]	;@7F9F
FindMonster_Loop:	cmp byte ptr [si], 0	; empty	;@7FA3
	je FindMonster_Next	;@7FA6
	cmp dh, byte ptr [si+60h]	; MonY	;@7FA8
	jne FindMonster_Next	;@7FAB
	cmp dl, byte ptr [si+40h]	; MonX	;@7FAD
	je FindMonster_Found	;@7FB0
FindMonster_Next:	dec si	;@7FB2
	loop FindMonster_Loop	;@7FB3
	mov bx, 0FFFFh	;@7FB5
FindMonster_Done:	pop si	;@7FB8
	pop cx	;@7FB9
	popf	;@7FBA
	ret	;@7FBB
FindMonster_Found:	lea bx, MonTile	;@7FBC
	xchg bx, si	;@7FC0
	sub bx, si	;@7FC2
	jmp FindMonster_Done	;@7FC4
;------------------------------------------------------------------------------
; CmdTransact: T, "Who will/Transact?". Asks a player and a direction.
; - A creature there: Lord British (tile 4Ch = shape 19) raises the maximum hit points by 100
;   (one level) if the experience's hundreds reach the maximum's hundreds ("Experience
;   more!" if not), up to 2500 ("No more!"), and from 500 on only with the Mark of Kings
;   ("Seek ye the Mark of Kings!"). Others answer by their MonTalk byte: 0C0h "Eat Death
;   Scum!", 0 "Good day!", n = speech n-1 of MapText.
; - No creature: a counter (map byte 94h-0E4h: a wall or sign letter) with a merchant (40h,
;   shape 16) behind it: the town service for the player's y & 7 (table ShopCmds), or the
;   Equine Emporium (ShopHorses) when facing west. The player's number is inverted meanwhile.
; - Otherwise "Not Here!". In: SI = the prompt. Ends at MainLoop.
;------------------------------------------------------------------------------
CmdTransact:	call PrintMsg	;@7FC6
	call AskPlayer	;@7FC9
	je CmdTransact_Done	;@7FCC
	mov di, ax	; DI = the player number (AL)	;@7FCE
	mov bp, bx	; BP = his record	;@7FD0
	call IsUp	;@7FD2
	jne CmdTransact_Incap	;@7FD5
	lea si, MsgTalkDirect	; "Direct? "	;@7FD7
	call PrintMsg	;@7FDB
	call AskDirection	;@7FDE
	je CmdTransact_Done	;@7FE1
	mov cx, dx	; CX = the step	;@7FE3
	xchg dx, bx	; DX = the cell	;@7FE5
	call FindMonster	;@7FE7
	cmp bx, -1	;@7FEA
	jne CmdTransact_Creature	;@7FED
	mov bx, dx	;@7FEF
	call MapCellAddr	;@7FF1
	cmp al, 94h	; shape 37, Wall ...	;@7FF4
	jb CmdTransact_NotHere	;@7FF6
	cmp al, 0E4h	; ... to 57, sign letter T	;@7FF8
	ja CmdTransact_NotHere	;@7FFA
	add dl, cl	; one cell further	;@7FFC
	add dh, ch	;@7FFE
	mov bx, dx	;@8000
	call MapCellAddr	;@8002
	cmp al, 40h	; Merchant	;@8005
	jne CmdTransact_NotHere	;@8007
	mov si, di	;@8009
	mov ax, di	;@800B
	call InvertPlayerNum	;@800D
	mov di, bp	; DI = the record for the service	;@8010
	cmp cx, 0FFh	; step (-1, 0): west	;@8012
	jne CmdTransact_Shop	;@8016
	call ShopHorses	; Equine Emporium	;@8018
	jmp short CmdTransact_Unmark	;@801B
CmdTransact_Shop:	mov al, byte ptr PlayerY	; the player's y	;@801D
	and al, 7	;@8020
	mov ah, 0	;@8022
	shl ax, 1	;@8024
	mov bx, ax	;@8026
	call word ptr ShopCmds[bx]	;@8028
CmdTransact_Unmark:	mov ax, si	;@802C
	call InvertPlayerNum	;@802E
CmdTransact_Done:	jmp MainLoop	;@8031
CmdTransact_NotHere:	jmp MsgNotHere	;@8034
CmdTransact_Incap:	jmp MsgIncapacitated	;@8037
CmdTransact_Creature:	lea di, MonTile	;@803A
	cmp byte ptr [bx+di], 4Ch	; Lord British (shape 19)	;@803E
	je CmdTransact_LordBrit	;@8041
	mov al, byte ptr Ofs80h[bx+di]	; MonTile + 80h = MonTalk	;@8043
	cmp al, 0C0h	; does not talk: hostile	;@8047
	je CmdTransact_EatDeath	;@8049
	and al, 3Fh	;@804B
	mov cx, 0	;@804D
	shr al, cl	; a shift by 0: does nothing	;@8050
	je CmdTransact_GoodDay	;@8052
	dec al	;@8054
	mov bl, al	;@8056
	mov bh, 0	;@8058
	shl bx, 1	;@805A
	mov si, word ptr MapText[bx]	; the speech's offset	;@805C
	lea si, MapText[si]	;@8060
	call PrintMsg	;@8064
	jmp CmdTransact_Done	;@8067
CmdTransact_EatDeath:	lea si, MsgEatDeath	; "Eat Death Scum!"	;@8069
	call PrintMsg	;@806D
	jmp CmdTransact_Done	;@8070
CmdTransact_GoodDay:	lea si, MsgGoodDay	; "Good day!"	;@8072
	call PrintMsg	;@8076
	jmp CmdTransact_Done	;@8079
CmdTransact_LordBrit:	lea si, MsgWelcomeChild	; "Welcome my child"	;@807B
	call PrintMsg	;@807F
	mov bx, bp	;@8082
	mov al, byte ptr [bx+1Dh]	; maximum hit points / 100	;@8084
	cmp al, byte ptr [bx+1Fh]	; experience / 100	;@8087
	ja CmdTransact_ExpMore	;@808A
	cmp al, 25h	; 2500 (BCD)	;@808C
	jae CmdTransact_NoMore	;@808E
	cmp al, 5	;@8090
	jb CmdTransact_LevelUp	;@8092
	mov ah, byte ptr [bx+0Eh]	;@8094
	and ah, 80h	; Mark of Kings	;@8097
	je CmdTransact_SeekKings	;@809A
CmdTransact_LevelUp:	add al, 1	; + 100 maximum hit points	;@809C
	daa	;@809E
	mov byte ptr [bx+1Dh], al	;@809F
	lea si, MsgThouGreater	; "Thou art greater"	;@80A2
	call PrintMsg	;@80A6
	call FlashView	;@80A9
	mov al, 0FDh	;@80AC
	mov bl, 80h	;@80AE
	mov bh, 40h	;@80B0
	call Sound	;@80B2
	call FlashView	;@80B5
	jmp CmdTransact_Done	;@80B8
CmdTransact_SeekKings:	lea si, MsgSeekKings	; "Seek ye the Mark of Kings!"	;@80BB
	call PrintMsg	;@80BF
	jmp CmdTransact_Done	;@80C2
CmdTransact_NoMore:	lea si, MsgNoMore	; "No more!"	;@80C5
	call PrintMsg	;@80C9
	jmp CmdTransact_Done	;@80CC
CmdTransact_ExpMore:	lea si, MsgExpMore	; "Experience more!"	;@80CF
	call PrintMsg	;@80D3
	jmp CmdTransact_Done	;@80D6
;------------------------------------------------------------------------------
; ChestLoot: the contents of a chest for the player at DI (Get Chest, the dungeon
; chests, a spell at 61C5). "Gold+nn": (random(100) | 30h) mod 100, so 48-63 or 12-27 gold
; (AddGold adds it, at most 9999). Then 1 time in 4 an item: a weapon 1-7 (Dagger to Sword,
; "and a Dagger") or, failing that, an armour 1-3 (Cloth to Chain, "and Leather"), the
; index being the AND of two random numbers; at most 99 of each. In: DI. Uses: nothing.
;------------------------------------------------------------------------------
ChestLoot:	pushf	;@80D9
	push ax	;@80DA
	push bx	;@80DB
	push cx	;@80DC
	push dx	;@80DD
	push si	;@80DE
	lea si, MsgGoldPlus	; "Gold+"	;@80DF
	call PrintMsg	;@80E3
	mov dh, 64h	; 0-99	;@80E6
	call Random	;@80E8
	or dl, 30h	;@80EB
	cmp dl, 64h	;@80EE
	jb ChestLoot_Gold	;@80F1
	sub dl, 64h	;@80F3
ChestLoot_Gold:	mov al, dl	;@80F6
	aam	; to BCD	;@80F8
	mov cl, 4	;@80FA
	shl ah, cl	;@80FC
	or al, ah	;@80FE
	mov ah, 0	;@8100
	call PrintBcdByte	;@8102
	call ScrollMsg	;@8105
	mov bx, di	;@8108
	call AddGold	; gold += AL	;@810A
	mov dh, 0FFh	;@810D
	call Random	;@810F
	cmp dl, 40h	; 1 in 4: an item	;@8112
	jae ChestLoot_Done	;@8115
	call Random	;@8117
	test dl, 0FFh	;@811A
	js ChestLoot_TryArmour	;@811D
	mov al, dl	;@811F
	call Random	;@8121
	and dl, al	;@8124
	and dl, 7	; weapon 1-7	;@8126
	je ChestLoot_TryArmour	;@8129
	lea si, MsgAndA	; "and a "	;@812B
	call PrintMsg	;@812F
	mov al, dl	;@8132
	add al, 41h	; name 40h+n: a weapon	;@8134
	call PrintName	;@8136
	call ScrollMsg	;@8139
	mov bl, dl	;@813C
	mov bh, 0	;@813E
	mov al, byte ptr [bx+di+30h]	; weapons owned	;@8140
	add al, 1	;@8143
	daa	;@8145
	mov byte ptr [bx+di+30h], al	;@8146
	jae ChestLoot_Done	;@8149
	mov byte ptr [bx+di+30h], 99h	;@814B
	jmp short ChestLoot_Done	;@814F
ChestLoot_TryArmour:	call Random	;@8151
	test dl, 0FFh	;@8154
	js ChestLoot_Done	;@8157
	mov al, dl	;@8159
	call Random	;@815B
	and dl, al	;@815E
	and dl, 3	; armour 1-3	;@8160
	je ChestLoot_Done	;@8163
	lea si, MsgAnd	; "and "	;@8165
	call PrintMsg	;@8169
	mov al, dl	;@816C
	add al, 51h	; name 50h+n: an armour	;@816E
	call PrintName	;@8170
	call ScrollMsg	;@8173
	mov bl, dl	;@8176
	mov bh, 0	;@8178
	mov al, byte ptr [bx+di+28h]	; armours owned	;@817A
	add al, 1	;@817D
	daa	;@817F
	mov byte ptr [bx+di+28h], al	;@8180
	jae ChestLoot_Done	;@8183
	mov byte ptr [bx+di+28h], 99h	;@8185
ChestLoot_Done:	pop si	;@8189
	pop dx	;@818A
	pop cx	;@818B
	pop bx	;@818C
	pop ax	;@818D
	popf	;@818E
	ret	;@818F
CODE ENDS
END
